JS='''const slides=[...document.querySelectorAll('.slide')];let current=0;function go(n){current=Math.max(0,Math.min(slides.length-1,n));slides[current].scrollIntoView({behavior:'instant'});history.replaceState(null,'','#'+slides[current].id);update()}function update(){document.querySelector('#pagecount').textContent=(current+1)+' / '+slides.length;document.querySelector('#sections').value=slides[current].id}document.querySelector('#prev').onclick=()=>go(current-1);document.querySelector('#next').onclick=()=>go(current+1);document.querySelector('#sections').onchange=e=>go(slides.findIndex(s=>s.id===e.target.value));document.querySelector('#print').onclick=()=>window.print();document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(current+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(current-1)}});window.addEventListener('scroll',()=>{let n=0;slides.forEach((s,i)=>{if(s.getBoundingClientRect().top<innerHeight*.45)n=i});current=n;update()},{passive:true});document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{const s=b.previousElementSibling.textContent;try{await navigator.clipboard.writeText(s)}catch{const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();document.execCommand('copy');t.remove()}document.querySelector('#copystatus').textContent='คัดลอกแล้ว';b.textContent='คัดลอกแล้ว'});if(location.hash){const i=slides.findIndex(s=>'#'+s.id===location.hash);if(i>=0)go(i)}'''
page='<!doctype html><html lang="th"><head><meta charset="utf-8"><link rel="icon" href="data:,"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 2 · Prompt กับ Skill — แก้ปัญหาการทำงานด้วย AI</title><style>'+CSS+'</style></head><body><header class="hero"><div class="eyebrow">WEEK 02 • AI AT WORK</div><h1>แก้ปัญหาการทำงานด้วย AI<br>Prompt ทั่วไป กับ Skill</h1><p>เก็บวิธีทำงานไว้ใช้ซ้ำ และตรวจว่าผลดีขึ้นจริงหรือไม่<br>สาม Lab จากงานร้านค้า • ใช้ภาษาคน • ไม่ต้องเขียนโปรแกรม</p><p><span class="pill">หลักฐานก่อนข้อสรุป</span><span class="pill">cyolo1 · gpt-6-astra · high</span><span class="pill">ฉบับ 12 กันยายน 2026</span></p></header>'+nav+'<main>'+''.join(f'<section class="slide" id="{id}"><div class="slide-head"><span class="num">{n:02}</span><span>{section}</span></div><h2>{title}</h2>{content}</section>' for n,(id,title,content,section) in enumerate(slides,1))+'</main><footer>Week2 • เรียนจากหลักฐานใหม่ ไม่สืบทอดผลทดลอง Week1 • <a href="sources.html">แหล่งอ้างอิง</a></footer><script>'+JS+'</script></body></html>'
