labels=['กลุ่ม','Lab','ชุด','P/S','ลำดับ','ร่างแรก /12','ฉบับแก้ /12','ข้ออ้างรองรับ','ข้ออ้างทั้งหมด','เวลาคน วินาที','เวลาเครื่อง วินาที','ครั้งช่วยแก้','คำใบ้','C /4','setup นาที','สร้าง นาที','ปรับ นาที','หลักฐาน/ID','สิ่งที่ต้องแก้','ชื่อตัวชี้วัดเฉพาะ Lab','ค่าที่วัดจริง']
scorejs='''const cols=COLS;const key='week2-scorecard-v1';let rows=[];try{rows=JSON.parse(localStorage.getItem(key)||'[]')}catch{}if(!Array.isArray(rows)||!rows.length)rows=[{}];const body=document.querySelector('tbody'),status=document.querySelector('#status');function save(){try{localStorage.setItem(key,JSON.stringify(rows));status.textContent='บันทึกใน browser นี้แล้ว'}catch{status.textContent='browser ไม่อนุญาตเก็บข้อมูล กรุณาดาวน์โหลด CSV'}}function render(){body.innerHTML='';rows.forEach((r,i)=>{const tr=document.createElement('tr');cols.forEach(c=>{const td=document.createElement('td'),input=document.createElement('input');input.value=r[c]||'';input.setAttribute('aria-label',c+' row '+(i+1));input.placeholder='not-measured';input.addEventListener('input',()=>{rows[i][c]=input.value;save()});td.append(input);tr.append(td)});body.append(tr)})}document.querySelector('#add').onclick=()=>{rows.push({});render();save()};function csvcell(x){let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}document.querySelector('#download').onclick=()=>{const csv='\\ufeff'+[cols,...rows.map(r=>cols.map(c=>r[c]||'not-measured'))].map(r=>r.map(csvcell).join(',')).join('\\r\\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='week2-scorecard.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status.textContent='ดาวน์โหลด CSV แล้ว'};document.querySelector('#print').onclick=()=>print();render();'''.replace('COLS',json.dumps(columns))
score='<!doctype html><html lang="th"><head><meta charset="utf-8"><link rel="icon" href="data:,"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week2 scorecard</title><style>'+CSS+'</style></head><body><main><article class="document"><p><a href="index.html#measure">← กลับสไลด์</a></p><h1>บันทึกผลที่สังเกตจริง</h1><p>กรอกทีละรอบ ค่าว่างส่งออกเป็น not-measured ไม่ใช่ศูนย์ คะแนนร่างแรกและฉบับแก้ต้องตรวจตามรูบริก ไม่มีคะแนนตั้งไว้ล่วงหน้า</p><div class="callout">ข้อมูลเก็บเฉพาะ browser นี้ ไม่ส่งขึ้นระบบ ใช้ดาวน์โหลด CSV เพื่อส่งงาน/สำรองก่อนเปลี่ยนเครื่อง</div><p><button id="add">เพิ่มแถว</button> <button id="download">ดาวน์โหลด CSV</button> <button id="print">พิมพ์</button></p><p id="status" role="status">พร้อมกรอก</p><div class="table-wrap"><table class="score-table"><thead><tr>'+''.join('<th>'+x+'</th>' for x in labels)+'</tr></thead><tbody></tbody></table></div><p class="small">P = Prompt ขั้นตอนครบ · S = native Skill · accuracy = รองรับ/ตรวจทั้งหมด (เมื่อได้นับจริง) · completeness = ผ่านรูบริก/12 · การแก้/คำใบ้ของคนใน technical pilot ไม่ได้วัด</p><p><a href="instructor/protocol.html">นิยามและวิธีเปรียบเทียบ</a></p></article></main><script>'+scorejs+'</script></body></html>'
put('scorecard.html',score)
