# Companion docs: generated HTML with inline styling, relative links adjusted.
import mistune
md=mistune.create_markdown(plugins=['table','strikethrough'])
from lab_paths import LAB_DIRS
def eligible(p):
 try:parts=p.relative_to(ROOT).parts
 except ValueError:return False
 return p.exists() and (not parts or parts[0] not in LAB_DIRS.values()) and not any(x in parts for x in ['.agents','experiments','learner-results','test-results','.ipynb_checkpoints']) and p.name!='SKILL.md' and not ('creation' in parts and p.name!='README.md')
for p in ROOT.rglob('*.md'):
 if not eligible(p):continue
 content=md(p.read_text()).replace('<table>', '<div class="table-wrap"><table>').replace('</table>', '</table></div>')
 def rewrite(m):
  target=(p.parent/(m[1]+'.md')).resolve()
  return 'href="'+m[1]+'.html'+(m[2] or '')+'"' if eligible(target) else m[0]
 content=re.sub(r'href="([^"#]+)\.md(#[^"]*)?"',rewrite,content)
 relative='../'*len(p.relative_to(ROOT).parts[:-1])
 content='<!doctype html><html lang="th"><head><meta charset="utf-8"><link rel="icon" href="data:,"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(p.stem)+' · Week2</title><style>'+CSS+'</style></head><body><main><article class="document"><p><a href="'+relative+'index.html">← สไลด์ Week2</a></p>'+content+'</article></main></body></html>'
 p.with_suffix('.html').write_text(content)
